package de.kumpewo.autohotkey.psi;

import com.intellij.psi.tree.IElementType;
import de.kumpewo.autohotkey.AhkLanguage;
import org.jetbrains.annotations.NotNull;

/** Type of the lexer tokens generated by Grammar-Kit (constants in {@code AhkTypes}). */
public class AhkTokenType extends IElementType {
    public AhkTokenType(@NotNull String debugName) {
        super(debugName, AhkLanguage.INSTANCE);
    }

    /** Debug name with prefix, shown in the PSI viewer. */
    @Override
    public String toString() {
        return "AhkTokenType." + super.toString();
    }
}
